{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "envelope.v1.json",
  "title": "Event envelope",
  "description": "Envelope every cross-service event travels in. Each event schema restates these fields and pins eventType with const.",
  "type": "object",
  "required": [
    "eventId",
    "eventType",
    "timestamp",
    "source",
    "payload"
  ],
  "additionalProperties": false,
  "properties": {
    "eventId": {
      "type": "string",
      "format": "uuid"
    },
    "eventType": {
      "type": "string",
      "description": "Event name, e.g. order.created."
    },
    "timestamp": {
      "type": "string",
      "format": "date-time"
    },
    "source": {
      "type": "string",
      "description": "Publishing service name."
    },
    "correlationId": {
      "type": "string",
      "description": "Propagated from the inbound request."
    },
    "version": {
      "type": "integer",
      "const": 1
    },
    "payload": {
      "type": "object",
      "description": "Event-specific body. Pin its fields per event in this file.",
      "additionalProperties": true
    }
  }
}

