import { createServer, request } from 'node:http';
import {
  attachCorrelationId,
  correlationHeaders,
  createLogger,
  healthResponse,
  HEALTH_LIVE_PATH,
  HEALTH_LEGACY_PATH,
  HEALTH_LEGACY_READY_PATH,
  HEALTH_READY_PATH,
  installGracefulShutdown,
  instrumentRoute,
  logRequest,
  METRICS_PATH,
  processStartTimeSeconds,
  readinessResponse,
  renderMetrics,
  CircuitBreaker,
  IDEMPOTENCY_HEADER,
  RESILIENCE_DEFAULTS,
  idempotencyKeyOf,
  AuthError,
  authenticateRequest,
  describeSecrets,
  isPublicPath,
  securityConfigFromEnv,
  stampedIdentityHeaders,
  EDGE_SHARED_SECRET_ENV,
  EDGE_SHARED_SECRET_PREVIOUS_ENV,
} from '@demo-app/shared';

const SERVICE = 'gateway';
const VERSION = '0.1.0';
const PORT = Number(process.env.PORT ?? 4000);
const logger = createLogger({ service: SERVICE, version: VERSION });
processStartTimeSeconds.set(Math.round(Date.now() / 1000 - process.uptime()));
const EDGE_SECRET = process.env.EDGE_AUTH_SHARED_SECRET ?? '';
const security = securityConfigFromEnv(process.env);
logger.info('security.configured', { issuer: security.issuer, audience: security.audience, algorithms: security.algorithms, keyCount: security.keys.length });
logger.info('security.secrets', { state: describeSecrets(process.env, [EDGE_SHARED_SECRET_ENV, EDGE_SHARED_SECRET_PREVIOUS_ENV]) });

/** Path prefix → upstream service base URL. */
const routes: Record<string, string> = {
  '/api/v1/users': process.env.USERS_URL ?? 'http://localhost:4001',
  '/api/v1/orders': process.env.ORDERS_URL ?? 'http://localhost:4002',
  '/api/v1/notifications': process.env.NOTIFICATIONS_URL ?? 'http://localhost:4003',
};

/** One breaker per upstream prefix: a sick dependency is cut off, not queued
 * against. */
const breakers = new Map<string, CircuitBreaker>();
const breakerFor = (prefix: string): CircuitBreaker => {
  let breaker = breakers.get(prefix);
  if (!breaker) {
    breaker = new CircuitBreaker(prefix);
    breakers.set(prefix, breaker);
  }
  return breaker;
};

const server = createServer((req, res) => {
  const url = (req.url ?? '/').split('?')[0];
  const requestStartedAt = Date.now();
  const correlationId = attachCorrelationId(req, res);
  logRequest(logger.child({ correlationId }), req);
  res.on('finish', () => {
    instrumentRoute(req.method ?? 'GET', url, res.statusCode, requestStartedAt);
  });

  if (url === HEALTH_LIVE_PATH || url === HEALTH_LEGACY_PATH) {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify(healthResponse(SERVICE, VERSION)));
    return;
  }

  if (url === HEALTH_READY_PATH || url === HEALTH_LEGACY_READY_PATH) {
    const payload = readinessResponse(SERVICE, VERSION);
    res.writeHead(payload.status === 'ok' ? 200 : 503, { 'content-type': 'application/json' });
    res.end(JSON.stringify(payload));
    return;
  }

  if (url === METRICS_PATH) {
    res.writeHead(200, { 'content-type': 'text/plain; version=0.0.4; charset=utf-8' });
    res.end(renderMetrics());
    return;
  }
  if (!isPublicPath(url)) {
    let principal;
    try {
      principal = authenticateRequest(req.headers, security);
    } catch (error) {
      const rejection = error as AuthError;
      logger.warn('auth.rejected', { code: rejection.code, path: url });
      res.writeHead(rejection.status ?? 401, {
        'content-type': 'application/json',
        'www-authenticate': rejection.wwwAuthenticate ?? 'Bearer',
      });
      res.end(JSON.stringify({ error: rejection.code }));
      return;
    }
    // The services never see the bearer token, only this identity.
    Object.assign(req.headers, stampedIdentityHeaders(principal, EDGE_SECRET));
  }

  const prefix = Object.keys(routes).find((key) => url === key || url.startsWith(key + '/'));
  if (!prefix) {
    res.writeHead(404, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'no route for ' + url }));
    return;
  }

  if (req.method === 'POST' && !idempotencyKeyOf(req.headers)) {
    res.writeHead(400, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: IDEMPOTENCY_HEADER + ' header is required for POST' }));
    return;
  }

  const breaker = breakerFor(prefix);
  if (breaker.state === 'open') {
    res.writeHead(503, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'upstream ' + prefix + ' unavailable', reason: 'circuit-open' }));
    return;
  }

  const target = new URL(routes[prefix] + url);
  const upstream = request(
    {
      hostname: target.hostname,
      port: target.port,
      path: target.pathname + target.search,
      method: req.method,
      headers: { ...req.headers, host: target.host, ...correlationHeaders(req, correlationId) },
    },
    (upstreamRes) => {
      res.writeHead(upstreamRes.statusCode ?? 502, upstreamRes.headers);
      upstreamRes.pipe(res);
      // The body streams straight through, so the breaker is told the outcome
      // directly instead of wrapping the whole exchange in one promise.
      if ((upstreamRes.statusCode ?? 502) >= 500) breaker.recordFailure();
      else breaker.recordSuccess();
    }
  );
  upstream.on('error', (error) => {
    res.writeHead(502, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ error: 'upstream ' + prefix + ' unavailable', detail: String(error) }));
    breaker.recordFailure();
  });
  upstream.setTimeout(RESILIENCE_DEFAULTS.timeoutMs, () => {
    upstream.destroy(new Error('upstream ' + prefix + ' timed out'));
  });
  req.pipe(upstream);
});

installGracefulShutdown(server, logger);
server.listen(PORT, () => {
  logger.info('server.listening', { port: PORT });
  for (const [prefix, base] of Object.entries(routes)) {
    logger.info('gateway.route', { prefix, base });
  }
});

